    19	import java.util.Map;
    20	import java.util.TreeMap;
    21	
    22	/**
    23	 * Maps exceptions to RFC 7807 {@link ProblemDetail} responses ({@code application/problem+json}).
    24	 * Validation problems carry an extra {@code errors} property (field/property path to message).
    25	 * 401/403 are produced by the security entry points (step 7); unexpected exceptions are left to Spring's
    26	 * default handling.
    27	 */
    28	@RestControllerAdvice
    29	@Slf4j
    30	public class GlobalExceptionHandler {
    31	
    32	    private static final String ERRORS = "errors";
    33	
    34	    @ExceptionHandler(MethodArgumentNotValidException.class)
    35	    public ProblemDetail handleMethodArgumentNotValid(MethodArgumentNotValidException ex) {
    36	        Map<String, String> errors = new TreeMap<>();
    37	        ex.getBindingResult().getFieldErrors().forEach(
    38	                error -> errors.putIfAbsent(error.getField(), messageOf(error)));
    39	        ProblemDetail problem = problem(HttpStatus.BAD_REQUEST, "Validation failed", "Request validation failed");
    40	        problem.setProperty(ERRORS, errors);
    41	        return problem;
    42	    }
    43	
    44	    @ExceptionHandler(ConstraintViolationException.class)
    45	    public ProblemDetail handleConstraintViolation(ConstraintViolationException ex) {
    46	        Map<String, String> errors = new TreeMap<>();
    47	        for (ConstraintViolation<?> violation : ex.getConstraintViolations()) {
    48	            errors.putIfAbsent(String.valueOf(violation.getPropertyPath()), violation.getMessage());
    49	        }
    50	        ProblemDetail problem = problem(HttpStatus.BAD_REQUEST, "Validation failed", "Request validation failed");
    51	        problem.setProperty(ERRORS, errors);
    52	        return problem;
    53	    }
    54	
    55	    @ExceptionHandler(HttpMessageNotReadableException.class)
    56	    public ProblemDetail handleNotReadable(HttpMessageNotReadableException ex) {
    57	        return problem(HttpStatus.BAD_REQUEST, "Malformed request", "Request body is missing or malformed");
    58	    }
    59	
    60	    @ExceptionHandler(MethodArgumentTypeMismatchException.class)
    61	    public ProblemDetail handleTypeMismatch(MethodArgumentTypeMismatchException ex) {
    62	        return problem(HttpStatus.BAD_REQUEST, "Invalid parameter",
    63	                "Parameter '" + ex.getName() + "' has an invalid value '" + ex.getValue() + "'");
    64	    }
    65	
    66	    @ExceptionHandler(MissingServletRequestParameterException.class)
    67	    public ProblemDetail handleMissingParameter(MissingServletRequestParameterException ex) {
    68	        return problem(HttpStatus.BAD_REQUEST, "Missing parameter",
    69	                "Required parameter '" + ex.getParameterName() + "' is missing");
    70	    }
    71	
    72	    @ExceptionHandler(ValidationException.class)
    73	    public ProblemDetail handleValidation(ValidationException ex) {
    74	        return problem(HttpStatus.BAD_REQUEST, "Validation failed", ex.getMessage());
    75	    }
    76	
    77	    @ExceptionHandler(NotFoundException.class)
    78	    public ProblemDetail handleNotFound(NotFoundException ex) {
    79	        return problem(HttpStatus.NOT_FOUND, "Not found", ex.getMessage());
    80	    }
    81	
    82	    @ExceptionHandler(ConflictException.class)
    83	    public ProblemDetail handleConflict(ConflictException ex) {
    84	        return problem(HttpStatus.CONFLICT, "Conflict", ex.getMessage());
    85	    }
    86	
    87	    private static ProblemDetail problem(HttpStatus status, String title, String detail) {
    88	        log.debug("Responding {} {}: {}", status.value(), title, detail);
    89	        ProblemDetail problem = ProblemDetail.forStatusAndDetail(status, detail);
    90	        problem.setTitle(title);
    91	        return problem;
    92	    }
    93	
    94	    private static String messageOf(FieldError error) {
    95	        return error.getDefaultMessage() == null ? "invalid value" : error.getDefaultMessage();
    96	    }
    97	}
