     1	package sk.knizat.tennisclub.service.impl;
     2	
     3	import lombok.RequiredArgsConstructor;
     4	import org.springframework.stereotype.Service;
     5	import org.springframework.transaction.annotation.Transactional;
     6	import sk.knizat.tennisclub.dao.SurfaceTypeDao;
     7	import sk.knizat.tennisclub.dto.surfacetype.SurfaceTypeRequest;
     8	import sk.knizat.tennisclub.dto.surfacetype.SurfaceTypeResponse;
     9	import sk.knizat.tennisclub.entity.SurfaceType;
    10	import sk.knizat.tennisclub.exception.ConflictException;
    11	import sk.knizat.tennisclub.exception.NotFoundException;
    12	import sk.knizat.tennisclub.mapper.SurfaceTypeMapper;
    13	import sk.knizat.tennisclub.service.SurfaceTypeService;
    14	
    15	import java.time.Clock;
    16	import java.util.List;
    17	
    18	/** Default {@link SurfaceTypeService} backed by {@link SurfaceTypeDao}. */
    19	@Service
    20	@Transactional
    21	@RequiredArgsConstructor
    22	public class SurfaceTypeServiceImpl implements SurfaceTypeService {
    23	
    24	    private static final String ENTITY = "SurfaceType";
    25	
    26	    private final SurfaceTypeDao surfaceTypeDao;
    27	    private final SurfaceTypeMapper mapper;
    28	    private final Clock clock;
    29	
    30	    @Override
    31	    @Transactional(readOnly = true)
    32	    public List<SurfaceTypeResponse> findAll() {
    33	        return surfaceTypeDao.findAll().stream().map(mapper::toResponse).toList();
    34	    }
    35	
    36	    @Override
    37	    @Transactional(readOnly = true)
    38	    public SurfaceTypeResponse findById(Long id) {
    39	        return mapper.toResponse(getOrThrow(id));
    40	    }
    41	
    42	    @Override
    43	    public SurfaceTypeResponse create(SurfaceTypeRequest request) {
    44	        String name = mapper.normaliseName(request.name());
    45	        if (surfaceTypeDao.findByName(name).isPresent()) {
    46	            throw duplicateName(name);
    47	        }
    48	        SurfaceType saved = surfaceTypeDao.save(mapper.toEntity(request));
    49	        return mapper.toResponse(saved);
    50	    }
    51	
    52	    @Override
    53	    public SurfaceTypeResponse update(Long id, SurfaceTypeRequest request) {
    54	        SurfaceType entity = getOrThrow(id);
    55	        String name = mapper.normaliseName(request.name());
    56	        boolean takenByOther = surfaceTypeDao.findByName(name)
    57	                .map(other -> !other.getId().equals(id))
    58	                .orElse(false);
    59	        if (takenByOther) {
    60	            throw duplicateName(name);
    61	        }
    62	        mapper.updateEntity(entity, request);
    63	        return mapper.toResponse(surfaceTypeDao.save(entity));
    64	    }
    65	
    66	    @Override
    67	    public void delete(Long id) {
    68	        SurfaceType entity = getOrThrow(id);
    69	        long courts = surfaceTypeDao.countCourtsUsing(id);
    70	        if (courts > 0) {
    71	            throw new ConflictException(
    72	                    "SurfaceType with id " + id + " is used by " + courts + " court(s) and cannot be deleted");
    73	        }
    74	        surfaceTypeDao.softDelete(entity, clock.instant());
    75	    }
    76	
    77	    private SurfaceType getOrThrow(Long id) {
    78	        return surfaceTypeDao.findById(id).orElseThrow(() -> NotFoundException.of(ENTITY, id));
    79	    }
    80	
    81	    private static ConflictException duplicateName(String name) {
    82	        return new ConflictException("SurfaceType with name '" + name + "' already exists");
    83	    }
    84	}

